"""Construct nested continuous brush paths from the visible exemplar silhouette."""
import numpy as np
from scipy.ndimage import distance_transform_edt,gaussian_filter1d
from PIL import Image,ImageDraw
MM=.2218603515625

def contours(m):
 # Clockwise directed edges around occupied image cells, pixel centres at integers.
 edges={}
 ys,xs=np.where(m)
 for y,x in zip(ys,xs):
  if y==0 or not m[y-1,x]:edges[(x-.5,y-.5)]=(x+.5,y-.5)
  if x==m.shape[1]-1 or not m[y,x+1]:edges[(x+.5,y-.5)]=(x+.5,y+.5)
  if y==m.shape[0]-1 or not m[y+1,x]:edges[(x+.5,y+.5)]=(x-.5,y+.5)
  if x==0 or not m[y,x-1]:edges[(x-.5,y+.5)]=(x-.5,y-.5)
 loops=[]
 while edges:
  start=next(iter(edges));p=start;path=[]
  while p in edges:
   path.append(p);p=edges.pop(p)
   if p==start:break
  if len(path)>10:loops.append(np.array(path))
 return loops

def resample(p,step):
 d=np.r_[0,np.cumsum(np.linalg.norm(np.diff(p,axis=0),axis=1))];
 t=np.linspace(0,d[-1],int(np.ceil(d[-1]/step))+1)
 return np.c_[np.interp(t,d,p[:,0]),np.interp(t,d,p[:,1])]

def shape_path(k,scale=1,outer=.8,spacing=1.1):
 l=np.load('/app/output/target_components.npy');m=l==k;d=distance_transform_edt(m)*MM*scale
 loops=[]
 for lev in np.arange(outer,d.max(),spacing)[::-1]:
  for c in contours(d>=lev):
   c=gaussian_filter1d(c,1.5,axis=0,mode='wrap')
   loops.append((lev,c))
 # Innermost first, enter outer contours at the closest pair of points.
 full=[];last=None
 for lev,c in loops:
  if last is not None:
   i=np.argmin(np.linalg.norm(c-last,axis=1));c=np.roll(c,-i,axis=0)
  else:
   # Start at the deepest point of the innermost contour.
   i=np.argmax(d[np.clip(np.rint(c[:,1]).astype(int),0,1023),np.clip(np.rint(c[:,0]).astype(int),0,1023)])
   c=np.roll(c,-i,axis=0)
  c=np.r_[c,c[:1]]
  full.extend(c);last=c[-1]
 # Return to a safe interior point before lifting.
 c0=loops[0][1];j=np.argmin(np.linalg.norm(c0-last,axis=1));full.append(c0[j])
 return np.array(full),loops

if __name__=='__main__':
 im=Image.open('/app/target.png');dr=ImageDraw.Draw(im)
 for k in [1,2]:
  p,loops=shape_path(k)
  print(k,'length mm',np.linalg.norm(np.diff(p,axis=0),axis=1).sum()*MM,'loops',len(loops))
  for lev,c in loops:dr.line([tuple(t) for t in c],fill=(240,80,80),width=1)
 im.save('/app/output/contour_plan.png')
PY
